// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        // No restriction needed: every admissible input (any caller, any new owner)
        // must obey the rule on the reference.
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) { ok = true; } catch { ok = false; }
        // Rule: a call either reverts, or it is made by the current owner (the deployer,
        // address(this)). The mutant lets any non-address(0) caller succeed.
        assertTrue(!ok || caller == address(this));
    }
}
